#[allow(non_camel_case_types)]
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct URL {
    scheme: String,
    host: String,
    port: String,
    path: String,
}

impl URL {
    pub fn new(input: &str) -> Self {
        parse_url(strip_query_and_fragment(input))
    }

    pub fn is_valid_url(input: &str) -> bool {
        let stripped = strip_query_and_fragment(input);

        if stripped.is_empty() {
            return false;
        }

        let parsed = parse_url(stripped);
        !parsed.host.is_empty() || !parsed.path.is_empty()
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn port(&self) -> &str {
        &self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }
}

fn parse_url(stripped: &str) -> URL {
    let Some(scheme_end) = stripped.find("://") else {
        return URL {
            scheme: String::new(),
            host: String::new(),
            port: String::new(),
            path: stripped.to_string(),
        };
    };

    let scheme = &stripped[..scheme_end];
    let remainder = &stripped[scheme_end + 3..];

    let (authority, path) = match remainder.find('/') {
        Some(index) => (&remainder[..index], &remainder[index..]),
        None => (remainder, ""),
    };

    let (host, port) = match authority.find(':') {
        Some(index) => (&authority[..index], &authority[index + 1..]),
        None => (authority, ""),
    };

    URL {
        scheme: scheme.to_string(),
        host: host.to_string(),
        port: port.to_string(),
        path: path.to_string(),
    }
}

fn strip_query_and_fragment(input: &str) -> &str {
    let cutoff = input.find(['?', '#']).unwrap_or(input.len());
    &input[..cutoff]
}

