use rust_port::url_parser::{self, URL};

fn bool_as_int(value: bool) -> u8 {
    if value { 1 } else { 0 }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        std::process::exit(1);
    }

    let url = &args[1];

    println!("{}", bool_as_int(URL::is_valid_url(url)));

