    println!("{}", bool_as_int(url_parser::is_scheme_valid(parser.scheme())));
    println!("{}", bool_as_int(url_parser::is_host_valid(parser.host())));
    println!("{}", bool_as_int(url_parser::is_port_valid(parser.port())));

    let path_segments = url_parser::split_path(parser.path());
    println!("{}", path_segments.len());

    for segment in path_segments {
