pub fn is_scheme_valid(scheme: &str) -> bool {
    let mut chars = scheme.chars();
    let Some(first) = chars.next() else {
        return false;
    };

    first.is_ascii_alphabetic()
        && chars.all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '+' | '-' | '.'))
}

pub fn is_host_valid(host: &str) -> bool {
    !host.is_empty()
        && host.chars().all(|ch| {
            ch.is_ascii_alphanumeric() || matches!(ch, '.' | '-' | '[' | ']' | '@' | ':')
        })
}

pub fn is_port_valid(port: &str) -> bool {
    match parse_partial_i64(port) {
        Some(value) => (0..=65_535).contains(&value),
        None => false,
    }
}

fn parse_partial_i64(input: &str) -> Option<i64> {
    let trimmed = input.trim_start_matches(char::is_whitespace);
    let mut chars = trimmed.chars().peekable();

    let sign = match chars.peek().copied() {
        Some('+') => {
            chars.next();
            1_i128
        }
        Some('-') => {
            chars.next();
            -1_i128
        }
        _ => 1_i128,
    };

    let mut value = 0_i128;
    let mut saw_digit = false;

    while let Some(ch) = chars.peek().copied() {
        if !ch.is_ascii_digit() {
            break;
        }

        saw_digit = true;
        value = value.saturating_mul(10).saturating_add((ch as u8 - b'0') as i128);
        chars.next();
    }

    if !saw_digit {
        return None;
    }

    i64::try_from(sign.saturating_mul(value)).ok()
}

